import os
import importlib.util
import pytest

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
top_n = target.top_n


def test_basic_descending():
    assert top_n([3, 1, 4, 1, 5, 9, 2, 6], 3) == [9, 6, 5]


def test_n_zero_returns_empty():
    assert top_n([3, 1, 2], 0) == []


def test_n_larger_than_size_returns_all_descending():
    assert top_n([2, 5, 1], 10) == [5, 2, 1]


def test_duplicates_preserved():
    assert top_n([7, 7, 3, 7], 2) == [7, 7]


def test_n_equal_size():
    assert top_n([1, 3, 2], 3) == [3, 2, 1]


def test_empty_input():
    assert top_n([], 3) == []


def test_negative_values():
    assert top_n([-5, -1, -3], 2) == [-1, -3]


def test_negative_n_raises():
    with pytest.raises(ValueError):
        top_n([1, 2], -1)


def test_non_list_raises():
    with pytest.raises(TypeError):
        top_n((1, 2), 1)


def test_non_int_values_raise():
    with pytest.raises(TypeError):
        top_n([1, 2.5], 1)

